insert into public.translations (locale, key, value) values
  ('pt-BR', 'beat.limitWait', $json$"{agent} atingiu o limite de uso; o JayV retoma este pedido às {time}"$json$::jsonb),
  ('pt-BR', 'beat.limitWait.estimated', $json$"{agent} atingiu o limite de uso e não disse quando ele volta; o JayV tenta de novo por volta das {time}"$json$::jsonb),
  ('pt-BR', 'chat.limitWait', $json$"{agent} atingiu o limite de uso. O JayV retoma este pedido sozinho às {time}."$json$::jsonb),
  ('pt-BR', 'chat.limitWait.estimated', $json$"{agent} atingiu o limite de uso e não disse quando ele volta. O JayV tenta de novo sozinho por volta das {time}."$json$::jsonb),
  ('pt-BR', 'chat.limitWait.resumeNow', $json$"Retomar agora"$json$::jsonb),
  ('pt-BR', 'chat.limitWait.resumeNow.title', $json$"Reenviar este pedido agora, sem esperar o limite voltar"$json$::jsonb),
  ('pt-BR', 'chat.limitWait.cancel', $json$"Não esperar"$json$::jsonb),
  ('pt-BR', 'chat.limitWait.cancel.title', $json$"Parar de esperar o limite; o pedido continua falho e pode ser reenviado à mão"$json$::jsonb),
  ('pt-BR', 'jev.resumeLimit', $json$"Retomar os pedidos quando o limite de uso do agente voltar"$json$::jsonb),
  ('pt-BR', 'jev.resumeLimit.hint', $json$"Quando um agente esgota o limite de uso e nenhum outro agente pode atender o pedido, o JayV guarda o pedido e o envia de novo sozinho quando o agente disser que o limite volta (com uma pequena margem). Se o agente não disser quando, tenta de novo em 30 minutos. O pedido que ainda bate no limite depois de três retomadas automáticas deixa de esperar. Desligado, o pedido fica falho até você reenviá-lo."$json$::jsonb),
  ('pt-BR', 'palette.resumeNow', $json$"Retomar agora o pedido que espera o limite de uso"$json$::jsonb),
  ('pt-BR', 'palette.cancelLimitWait', $json$"Parar de esperar o limite de uso"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.limitResume.title', $json$"Os pedidos são retomados quando o limite de uso volta"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.limitResume.detail', $json$"Quando um agente atinge o limite de uso e nenhum outro agente pode atender o pedido, ele não só falha: o JayV lê quando o agente diz que o limite volta, guarda o pedido e o envia de novo sozinho nessa hora, mesmo que o app tenha sido fechado no meio. O chat mostra a espera com a hora e deixa retomar agora ou parar de esperar. Em Configurações › Jev há uma chave para desligar."$json$::jsonb),
  ('pt-BR', 'docs.limitResume.title', $json$"Retomar depois do limite de uso"$json$::jsonb),
  ('pt-BR', 'docs.limitResume.summary', $json$"Quando um agente atinge o limite de uso e nenhum outro agente pode atender o pedido, o JayV guarda o pedido e o envia de novo sozinho quando o agente diz que o limite volta."$json$::jsonb),
  ('pt-BR', 'docs.limitResume.usage', $json$"Vem ligado (Configurações › Jev › Retomar os pedidos quando o limite de uso do agente voltar). Quando todos os agentes que poderiam responder esgotaram o limite, o pedido fica no chat como falho, com um aviso: qual agente parou e a hora em que o JayV vai retomá-lo, no seu horário, com um minuto de margem. Se o agente não diz quando o limite volta, o JayV tenta de novo em 30 minutos e o aviso diz que a hora é um palpite. Clique em Retomar agora para enviar antes, ou em Não esperar para cancelar a retomada automática; o pedido continua falho e Reenviar funciona como sempre (os dois também estão no Ctrl+K). A espera sobrevive ao fechamento do app: ao abrir depois da hora, o pedido é enviado. Se outro agente ligado estiver livre, o plano B já existente passa o pedido para ele na hora e nada espera. O pedido que ainda bate no limite depois de três retomadas automáticas deixa de esperar."$json$::jsonb),
  ('en', 'beat.limitWait', $json$"{agent} reached its usage limit; JayV resumes this request at {time}"$json$::jsonb),
  ('en', 'beat.limitWait.estimated', $json$"{agent} reached its usage limit and did not say when it comes back; JayV tries again around {time}"$json$::jsonb),
  ('en', 'chat.limitWait', $json$"{agent} reached its usage limit. JayV resumes this request by itself at {time}."$json$::jsonb),
  ('en', 'chat.limitWait.estimated', $json$"{agent} reached its usage limit and did not say when it comes back. JayV tries again by itself around {time}."$json$::jsonb),
  ('en', 'chat.limitWait.resumeNow', $json$"Resume now"$json$::jsonb),
  ('en', 'chat.limitWait.resumeNow.title', $json$"Resend this request now instead of waiting for the limit to come back"$json$::jsonb),
  ('en', 'chat.limitWait.cancel', $json$"Don't wait"$json$::jsonb),
  ('en', 'chat.limitWait.cancel.title', $json$"Stop waiting for the limit; the request stays failed and can be resent by hand"$json$::jsonb),
  ('en', 'jev.resumeLimit', $json$"Resume requests when an agent's usage limit comes back"$json$::jsonb),
  ('en', 'jev.resumeLimit.hint', $json$"When an agent runs out of its usage limit and no other agent can take the request, JayV keeps the request and sends it again by itself when the agent says the limit comes back (a few minutes later, with a margin). If the agent does not say when, it tries again in 30 minutes. A request that still hits the limit after three automatic resumes stops waiting. Off, the request stays failed until you resend it."$json$::jsonb),
  ('en', 'palette.resumeNow', $json$"Resume the request waiting for the usage limit now"$json$::jsonb),
  ('en', 'palette.cancelLimitWait', $json$"Stop waiting for the usage limit"$json$::jsonb),
  ('en', 'whatsNew.item.limitResume.title', $json$"Requests resume when the usage limit comes back"$json$::jsonb),
  ('en', 'whatsNew.item.limitResume.detail', $json$"When an agent reaches its usage limit and no other agent can take the request, the request no longer just fails: JayV reads when the agent says the limit comes back, keeps the request and sends it again by itself at that time, even if the app was closed in between. The chat shows the wait with the time, and lets you resume now or stop waiting. Settings › Jev has a switch to turn it off."$json$::jsonb),
  ('en', 'docs.limitResume.title', $json$"Resume after the usage limit"$json$::jsonb),
  ('en', 'docs.limitResume.summary', $json$"When an agent reaches its usage limit and no other agent can take the request, JayV keeps the request and sends it again by itself when the agent says the limit comes back."$json$::jsonb),
  ('en', 'docs.limitResume.usage', $json$"It is on by default (Settings › Jev › Resume requests when an agent's usage limit comes back). When every agent that could answer has run out of its limit, the request stays in the chat as failed with a note: which agent stopped and the time JayV will resume it, in your local time, with a one-minute margin. If an agent does not say when its limit comes back, JayV tries again in 30 minutes and the note says the time is a guess. Click Resume now to send it before that, or Don't wait to cancel the automatic resume; the request stays failed and Resend works as always (both are also in Ctrl+K). The wait survives closing the app: when it opens again after the time, the request is sent. If another enabled agent is free, the existing fallback moves the request to it right away and nothing waits. A request that still hits the limit after three automatic resumes stops waiting."$json$::jsonb),
  ('es', 'beat.limitWait', $json$"{agent} alcanzó su límite de uso; JayV retoma esta solicitud a las {time}"$json$::jsonb),
  ('es', 'beat.limitWait.estimated', $json$"{agent} alcanzó su límite de uso y no dijo cuándo vuelve; JayV lo intenta de nuevo hacia las {time}"$json$::jsonb),
  ('es', 'chat.limitWait', $json$"{agent} alcanzó su límite de uso. JayV retoma esta solicitud por sí solo a las {time}."$json$::jsonb),
  ('es', 'chat.limitWait.estimated', $json$"{agent} alcanzó su límite de uso y no dijo cuándo vuelve. JayV lo intenta de nuevo por sí solo hacia las {time}."$json$::jsonb),
  ('es', 'chat.limitWait.resumeNow', $json$"Retomar ahora"$json$::jsonb),
  ('es', 'chat.limitWait.resumeNow.title', $json$"Reenviar esta solicitud ahora, sin esperar a que vuelva el límite"$json$::jsonb),
  ('es', 'chat.limitWait.cancel', $json$"No esperar"$json$::jsonb),
  ('es', 'chat.limitWait.cancel.title', $json$"Dejar de esperar el límite; la solicitud sigue fallida y puede reenviarse a mano"$json$::jsonb),
  ('es', 'jev.resumeLimit', $json$"Retomar las solicitudes cuando vuelva el límite de uso del agente"$json$::jsonb),
  ('es', 'jev.resumeLimit.hint', $json$"Cuando un agente agota su límite de uso y ningún otro agente puede atender la solicitud, JayV la guarda y la envía de nuevo por sí solo cuando el agente diga que el límite vuelve (con un pequeño margen). Si el agente no dice cuándo, lo intenta de nuevo en 30 minutos. Una solicitud que sigue chocando con el límite tras tres reanudaciones automáticas deja de esperar. Desactivado, la solicitud queda fallida hasta que la reenvíes."$json$::jsonb),
  ('es', 'palette.resumeNow', $json$"Retomar ahora la solicitud que espera el límite de uso"$json$::jsonb),
  ('es', 'palette.cancelLimitWait', $json$"Dejar de esperar el límite de uso"$json$::jsonb),
  ('es', 'whatsNew.item.limitResume.title', $json$"Las solicitudes se retoman cuando vuelve el límite de uso"$json$::jsonb),
  ('es', 'whatsNew.item.limitResume.detail', $json$"Cuando un agente alcanza su límite de uso y ningún otro agente puede atender la solicitud, esta ya no solo falla: JayV lee cuándo dice el agente que el límite vuelve, guarda la solicitud y la envía de nuevo por sí solo a esa hora, aunque la app se haya cerrado mientras tanto. El chat muestra la espera con la hora y permite retomar ahora o dejar de esperar. En Configuración › Jev hay un interruptor para desactivarlo."$json$::jsonb),
  ('es', 'docs.limitResume.title', $json$"Retomar tras el límite de uso"$json$::jsonb),
  ('es', 'docs.limitResume.summary', $json$"Cuando un agente alcanza su límite de uso y ningún otro agente puede atender la solicitud, JayV la guarda y la envía de nuevo por sí solo cuando el agente dice que el límite vuelve."$json$::jsonb),
  ('es', 'docs.limitResume.usage', $json$"Viene activado (Configuración › Jev › Retomar las solicitudes cuando vuelva el límite de uso del agente). Cuando todos los agentes que podrían responder agotaron su límite, la solicitud queda en el chat como fallida con un aviso: qué agente se detuvo y la hora a la que JayV la retomará, en tu hora local, con un minuto de margen. Si el agente no dice cuándo vuelve el límite, JayV lo intenta de nuevo en 30 minutos y el aviso dice que la hora es una estimación. Haz clic en Retomar ahora para enviarla antes, o en No esperar para cancelar la reanudación automática; la solicitud sigue fallida y Reenviar funciona como siempre (ambas también están en Ctrl+K). La espera sobrevive al cierre de la app: al abrirla pasada la hora, la solicitud se envía. Si otro agente activado está libre, el plan B existente le pasa la solicitud al instante y nada espera. Una solicitud que sigue chocando con el límite tras tres reanudaciones automáticas deja de esperar."$json$::jsonb),
  ('zh-CN', 'beat.limitWait', $json$"{agent} 已达到使用限额；JayV 将在 {time} 恢复此请求"$json$::jsonb),
  ('zh-CN', 'beat.limitWait.estimated', $json$"{agent} 已达到使用限额，且未说明何时恢复；JayV 将在 {time} 前后重试"$json$::jsonb),
  ('zh-CN', 'chat.limitWait', $json$"{agent} 已达到使用限额。JayV 将在 {time} 自动恢复此请求。"$json$::jsonb),
  ('zh-CN', 'chat.limitWait.estimated', $json$"{agent} 已达到使用限额，且未说明何时恢复。JayV 将在 {time} 前后自动重试。"$json$::jsonb),
  ('zh-CN', 'chat.limitWait.resumeNow', $json$"立即恢复"$json$::jsonb),
  ('zh-CN', 'chat.limitWait.resumeNow.title', $json$"现在就重新发送此请求，不再等待限额恢复"$json$::jsonb),
  ('zh-CN', 'chat.limitWait.cancel', $json$"不再等待"$json$::jsonb),
  ('zh-CN', 'chat.limitWait.cancel.title', $json$"停止等待限额；请求保持失败状态，可手动重新发送"$json$::jsonb),
  ('zh-CN', 'jev.resumeLimit', $json$"代理的使用限额恢复后继续处理请求"$json$::jsonb),
  ('zh-CN', 'jev.resumeLimit.hint', $json$"当某个代理用完使用限额且没有其他代理可以处理请求时，JayV 会保留该请求，并在代理说明限额恢复时（加上少量余量）自动重新发送。如果代理没有说明时间，则 30 分钟后重试。自动恢复三次后仍触及限额的请求将不再等待。关闭后，请求会一直保持失败，直到你重新发送。"$json$::jsonb),
  ('zh-CN', 'palette.resumeNow', $json$"立即恢复正在等待使用限额的请求"$json$::jsonb),
  ('zh-CN', 'palette.cancelLimitWait', $json$"停止等待使用限额"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.limitResume.title', $json$"使用限额恢复后自动继续处理请求"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.limitResume.detail', $json$"当代理达到使用限额且没有其他代理可以处理请求时，请求不再直接失败：JayV 会读取代理所说的限额恢复时间，保留请求并在那个时间自动重新发送，即使期间应用被关闭。聊天会显示等待及其时间，并可立即恢复或停止等待。设置 › Jev 中有关闭它的开关。"$json$::jsonb),
  ('zh-CN', 'docs.limitResume.title', $json$"使用限额后继续"$json$::jsonb),
  ('zh-CN', 'docs.limitResume.summary', $json$"当代理达到使用限额且没有其他代理可以处理请求时，JayV 会保留该请求，并在代理说明限额恢复时自动重新发送。"$json$::jsonb),
  ('zh-CN', 'docs.limitResume.usage', $json$"默认开启（设置 › Jev › 代理的使用限额恢复后继续处理请求）。当所有可能回答的代理都用完限额时，请求会以失败状态留在聊天中并附带提示：哪个代理停止了，以及 JayV 将恢复它的时间（按你的本地时间，另加一分钟余量）。如果代理没有说明限额何时恢复，JayV 会在 30 分钟后重试，提示会注明该时间只是估计。点击“立即恢复”可提前发送，点击“不再等待”可取消自动恢复；请求保持失败，“重新发送”照常可用（两者也都在 Ctrl+K 中）。等待在关闭应用后依然有效：超过时间后再次打开应用，请求就会发送。如果另一个已启用的代理空闲，现有的备用方案会立即把请求交给它，不会产生等待。自动恢复三次后仍触及限额的请求将不再等待。"$json$::jsonb),
  ('hi', 'beat.limitWait', $json$"{agent} अपनी उपयोग सीमा तक पहुँच गया; JayV इस अनुरोध को {time} पर फिर शुरू करेगा"$json$::jsonb),
  ('hi', 'beat.limitWait.estimated', $json$"{agent} अपनी उपयोग सीमा तक पहुँच गया और उसने नहीं बताया कि सीमा कब लौटेगी; JayV लगभग {time} पर फिर कोशिश करेगा"$json$::jsonb),
  ('hi', 'chat.limitWait', $json$"{agent} अपनी उपयोग सीमा तक पहुँच गया। JayV इस अनुरोध को {time} पर अपने-आप फिर शुरू करेगा।"$json$::jsonb),
  ('hi', 'chat.limitWait.estimated', $json$"{agent} अपनी उपयोग सीमा तक पहुँच गया और उसने नहीं बताया कि सीमा कब लौटेगी। JayV लगभग {time} पर अपने-आप फिर कोशिश करेगा।"$json$::jsonb),
  ('hi', 'chat.limitWait.resumeNow', $json$"अभी फिर शुरू करें"$json$::jsonb),
  ('hi', 'chat.limitWait.resumeNow.title', $json$"सीमा लौटने का इंतज़ार किए बिना यह अनुरोध अभी दोबारा भेजें"$json$::jsonb),
  ('hi', 'chat.limitWait.cancel', $json$"इंतज़ार न करें"$json$::jsonb),
  ('hi', 'chat.limitWait.cancel.title', $json$"सीमा का इंतज़ार बंद करें; अनुरोध विफल रहेगा और हाथ से दोबारा भेजा जा सकता है"$json$::jsonb),
  ('hi', 'jev.resumeLimit', $json$"एजेंट की उपयोग सीमा लौटने पर अनुरोध फिर शुरू करें"$json$::jsonb),
  ('hi', 'jev.resumeLimit.hint', $json$"जब कोई एजेंट अपनी उपयोग सीमा खत्म कर दे और कोई दूसरा एजेंट अनुरोध न संभाल सके, तो JayV अनुरोध को रख लेता है और जब एजेंट बताता है कि सीमा लौट आती है (थोड़े अंतर के साथ), तब उसे अपने-आप दोबारा भेजता है। अगर एजेंट समय नहीं बताता, तो वह 30 मिनट बाद फिर कोशिश करता है। तीन स्वचालित पुनः-प्रयासों के बाद भी सीमा से टकराने वाला अनुरोध इंतज़ार करना बंद कर देता है। बंद करने पर अनुरोध तब तक विफल रहता है जब तक आप उसे दोबारा न भेजें।"$json$::jsonb),
  ('hi', 'palette.resumeNow', $json$"उपयोग सीमा का इंतज़ार कर रहे अनुरोध को अभी फिर शुरू करें"$json$::jsonb),
  ('hi', 'palette.cancelLimitWait', $json$"उपयोग सीमा का इंतज़ार बंद करें"$json$::jsonb),
  ('hi', 'whatsNew.item.limitResume.title', $json$"उपयोग सीमा लौटने पर अनुरोध फिर शुरू होते हैं"$json$::jsonb),
  ('hi', 'whatsNew.item.limitResume.detail', $json$"जब कोई एजेंट अपनी उपयोग सीमा तक पहुँच जाता है और कोई दूसरा एजेंट अनुरोध नहीं संभाल सकता, तो अनुरोध सिर्फ़ विफल नहीं होता: JayV पढ़ता है कि एजेंट के अनुसार सीमा कब लौटेगी, अनुरोध को रखता है और उसी समय उसे अपने-आप दोबारा भेजता है, भले ही बीच में ऐप बंद रहा हो। चैट इंतज़ार को समय के साथ दिखाती है और अभी फिर शुरू करने या इंतज़ार बंद करने देती है। सेटिंग › Jev में इसे बंद करने का स्विच है।"$json$::jsonb),
  ('hi', 'docs.limitResume.title', $json$"उपयोग सीमा के बाद फिर शुरू करें"$json$::jsonb),
  ('hi', 'docs.limitResume.summary', $json$"जब कोई एजेंट अपनी उपयोग सीमा तक पहुँच जाता है और कोई दूसरा एजेंट अनुरोध नहीं संभाल सकता, तो JayV अनुरोध को रखता है और जब एजेंट बताता है कि सीमा लौट आई, तब उसे अपने-आप दोबारा भेजता है।"$json$::jsonb),
  ('hi', 'docs.limitResume.usage', $json$"यह डिफ़ॉल्ट रूप से चालू है (सेटिंग › Jev › एजेंट की उपयोग सीमा लौटने पर अनुरोध फिर शुरू करें)। जब जवाब दे सकने वाले सभी एजेंट अपनी सीमा खत्म कर चुके हों, तो अनुरोध चैट में विफल के रूप में एक सूचना के साथ रहता है: कौन-सा एजेंट रुका और JayV उसे किस समय फिर शुरू करेगा, आपके स्थानीय समय में, एक मिनट के अंतर के साथ। अगर एजेंट नहीं बताता कि सीमा कब लौटेगी, तो JayV 30 मिनट बाद फिर कोशिश करता है और सूचना बताती है कि समय अनुमान है। पहले भेजने के लिए अभी फिर शुरू करें पर क्लिक करें, या स्वचालित पुनः-प्रारंभ रद्द करने के लिए इंतज़ार न करें पर; अनुरोध विफल रहता है और दोबारा भेजें हमेशा की तरह काम करता है (दोनों Ctrl+K में भी हैं)। इंतज़ार ऐप बंद करने पर भी बना रहता है: समय के बाद ऐप खुलने पर अनुरोध भेज दिया जाता है। अगर कोई दूसरा चालू एजेंट खाली है, तो मौजूदा वैकल्पिक योजना अनुरोध उसे तुरंत सौंप देती है और कुछ भी इंतज़ार नहीं करता। तीन स्वचालित पुनः-प्रारंभ के बाद भी सीमा से टकराने वाला अनुरोध इंतज़ार करना बंद कर देता है।"$json$::jsonb),
  ('ar', 'beat.limitWait', $json$"وصل {agent} إلى حد الاستخدام؛ سيستأنف JayV هذا الطلب في {time}"$json$::jsonb),
  ('ar', 'beat.limitWait.estimated', $json$"وصل {agent} إلى حد الاستخدام ولم يذكر متى يعود؛ سيعيد JayV المحاولة تقريبًا في {time}"$json$::jsonb),
  ('ar', 'chat.limitWait', $json$"وصل {agent} إلى حد الاستخدام. سيستأنف JayV هذا الطلب تلقائيًا في {time}."$json$::jsonb),
  ('ar', 'chat.limitWait.estimated', $json$"وصل {agent} إلى حد الاستخدام ولم يذكر متى يعود. سيعيد JayV المحاولة تلقائيًا تقريبًا في {time}."$json$::jsonb),
  ('ar', 'chat.limitWait.resumeNow', $json$"استئناف الآن"$json$::jsonb),
  ('ar', 'chat.limitWait.resumeNow.title', $json$"أعد إرسال هذا الطلب الآن دون انتظار عودة الحد"$json$::jsonb),
  ('ar', 'chat.limitWait.cancel', $json$"لا تنتظر"$json$::jsonb),
  ('ar', 'chat.limitWait.cancel.title', $json$"التوقف عن انتظار الحد؛ يبقى الطلب فاشلًا ويمكن إعادة إرساله يدويًا"$json$::jsonb),
  ('ar', 'jev.resumeLimit', $json$"استئناف الطلبات عند عودة حد استخدام الوكيل"$json$::jsonb),
  ('ar', 'jev.resumeLimit.hint', $json$"عندما ينفد حد استخدام وكيل ولا يستطيع أي وكيل آخر تنفيذ الطلب، يحتفظ JayV بالطلب ويعيد إرساله تلقائيًا عندما يقول الوكيل إن الحد يعود (مع هامش صغير). إذا لم يذكر الوكيل الموعد، يعيد المحاولة بعد 30 دقيقة. الطلب الذي ما زال يصطدم بالحد بعد ثلاث عمليات استئناف تلقائية يتوقف عن الانتظار. عند إيقاف الخيار يبقى الطلب فاشلًا حتى تعيد إرساله."$json$::jsonb),
  ('ar', 'palette.resumeNow', $json$"استئناف الطلب المنتظر لحد الاستخدام الآن"$json$::jsonb),
  ('ar', 'palette.cancelLimitWait', $json$"التوقف عن انتظار حد الاستخدام"$json$::jsonb),
  ('ar', 'whatsNew.item.limitResume.title', $json$"تُستأنف الطلبات عند عودة حد الاستخدام"$json$::jsonb),
  ('ar', 'whatsNew.item.limitResume.detail', $json$"عندما يصل وكيل إلى حد الاستخدام ولا يستطيع أي وكيل آخر تنفيذ الطلب، لا يفشل الطلب فحسب: يقرأ JayV متى يقول الوكيل إن الحد يعود، ويحتفظ بالطلب ويعيد إرساله تلقائيًا في ذلك الوقت، حتى لو أُغلق التطبيق في هذه الأثناء. تعرض المحادثة الانتظار مع الوقت وتتيح الاستئناف الآن أو التوقف عن الانتظار. في الإعدادات › Jev مفتاح لإيقافه."$json$::jsonb),
  ('ar', 'docs.limitResume.title', $json$"الاستئناف بعد حد الاستخدام"$json$::jsonb),
  ('ar', 'docs.limitResume.summary', $json$"عندما يصل وكيل إلى حد الاستخدام ولا يستطيع أي وكيل آخر تنفيذ الطلب، يحتفظ JayV بالطلب ويعيد إرساله تلقائيًا عندما يقول الوكيل إن الحد يعود."$json$::jsonb),
  ('ar', 'docs.limitResume.usage', $json$"الخيار مفعّل افتراضيًا (الإعدادات › Jev › استئناف الطلبات عند عودة حد استخدام الوكيل). عندما ينفد حد جميع الوكلاء الذين يمكنهم الإجابة، يبقى الطلب في المحادثة فاشلًا مع ملاحظة: أي وكيل توقف والوقت الذي سيستأنفه فيه JayV بتوقيتك المحلي مع هامش دقيقة. إذا لم يذكر الوكيل متى يعود الحد، يعيد JayV المحاولة بعد 30 دقيقة وتوضح الملاحظة أن الوقت تقدير. انقر على «استئناف الآن» للإرسال قبل ذلك، أو على «لا تنتظر» لإلغاء الاستئناف التلقائي؛ يبقى الطلب فاشلًا وتعمل «إعادة الإرسال» كالمعتاد (وكلاهما في Ctrl+K أيضًا). ويستمر الانتظار بعد إغلاق التطبيق: عند فتحه بعد الموعد يُرسَل الطلب. إذا كان وكيل آخر مفعّل متاحًا، تنقل الخطة البديلة الحالية الطلب إليه فورًا ولا ينتظر شيء. الطلب الذي ما زال يصطدم بالحد بعد ثلاث عمليات استئناف تلقائية يتوقف عن الانتظار."$json$::jsonb),
  ('fr', 'beat.limitWait', $json$"{agent} a atteint sa limite d'utilisation ; JayV reprend cette demande à {time}"$json$::jsonb),
  ('fr', 'beat.limitWait.estimated', $json$"{agent} a atteint sa limite d'utilisation sans dire quand elle revient ; JayV réessaie vers {time}"$json$::jsonb),
  ('fr', 'chat.limitWait', $json$"{agent} a atteint sa limite d'utilisation. JayV reprend cette demande tout seul à {time}."$json$::jsonb),
  ('fr', 'chat.limitWait.estimated', $json$"{agent} a atteint sa limite d'utilisation sans dire quand elle revient. JayV réessaie tout seul vers {time}."$json$::jsonb),
  ('fr', 'chat.limitWait.resumeNow', $json$"Reprendre maintenant"$json$::jsonb),
  ('fr', 'chat.limitWait.resumeNow.title', $json$"Renvoyer cette demande maintenant sans attendre le retour de la limite"$json$::jsonb),
  ('fr', 'chat.limitWait.cancel', $json$"Ne pas attendre"$json$::jsonb),
  ('fr', 'chat.limitWait.cancel.title', $json$"Arrêter d'attendre la limite ; la demande reste en échec et peut être renvoyée à la main"$json$::jsonb),
  ('fr', 'jev.resumeLimit', $json$"Reprendre les demandes quand la limite d'utilisation de l'agent revient"$json$::jsonb),
  ('fr', 'jev.resumeLimit.hint', $json$"Quand un agent épuise sa limite d'utilisation et qu'aucun autre agent ne peut traiter la demande, JayV la garde et la renvoie tout seul quand l'agent indique que la limite revient (avec une petite marge). Si l'agent n'indique pas quand, il réessaie dans 30 minutes. Une demande qui bute encore sur la limite après trois reprises automatiques cesse d'attendre. Désactivé, la demande reste en échec jusqu'à ce que vous la renvoyiez."$json$::jsonb),
  ('fr', 'palette.resumeNow', $json$"Reprendre maintenant la demande qui attend la limite d'utilisation"$json$::jsonb),
  ('fr', 'palette.cancelLimitWait', $json$"Arrêter d'attendre la limite d'utilisation"$json$::jsonb),
  ('fr', 'whatsNew.item.limitResume.title', $json$"Les demandes reprennent quand la limite d'utilisation revient"$json$::jsonb),
  ('fr', 'whatsNew.item.limitResume.detail', $json$"Quand un agent atteint sa limite d'utilisation et qu'aucun autre agent ne peut traiter la demande, celle-ci n'échoue plus simplement : JayV lit quand l'agent dit que la limite revient, garde la demande et la renvoie tout seul à ce moment-là, même si l'application a été fermée entre-temps. Le chat montre l'attente avec l'heure et permet de reprendre maintenant ou d'arrêter d'attendre. Un interrupteur dans Paramètres › Jev permet de le désactiver."$json$::jsonb),
  ('fr', 'docs.limitResume.title', $json$"Reprendre après la limite d'utilisation"$json$::jsonb),
  ('fr', 'docs.limitResume.summary', $json$"Quand un agent atteint sa limite d'utilisation et qu'aucun autre agent ne peut traiter la demande, JayV la garde et la renvoie tout seul quand l'agent dit que la limite revient."$json$::jsonb),
  ('fr', 'docs.limitResume.usage', $json$"Activé par défaut (Paramètres › Jev › Reprendre les demandes quand la limite d'utilisation de l'agent revient). Quand tous les agents qui pouvaient répondre ont épuisé leur limite, la demande reste dans le chat en échec avec une note : quel agent s'est arrêté et l'heure à laquelle JayV la reprendra, à votre heure locale, avec une minute de marge. Si l'agent ne dit pas quand sa limite revient, JayV réessaie dans 30 minutes et la note précise que l'heure est une estimation. Cliquez sur Reprendre maintenant pour l'envoyer plus tôt, ou sur Ne pas attendre pour annuler la reprise automatique ; la demande reste en échec et Renvoyer fonctionne comme toujours (les deux sont aussi dans Ctrl+K). L'attente survit à la fermeture de l'application : à la réouverture après l'heure, la demande est envoyée. Si un autre agent activé est libre, le plan B existant lui passe la demande tout de suite et rien n'attend. Une demande qui bute encore sur la limite après trois reprises automatiques cesse d'attendre."$json$::jsonb),
  ('ru', 'beat.limitWait', $json$"{agent} достиг лимита использования; JayV возобновит этот запрос в {time}"$json$::jsonb),
  ('ru', 'beat.limitWait.estimated', $json$"{agent} достиг лимита использования и не сообщил, когда он вернётся; JayV повторит попытку примерно в {time}"$json$::jsonb),
  ('ru', 'chat.limitWait', $json$"{agent} достиг лимита использования. JayV сам возобновит этот запрос в {time}."$json$::jsonb),
  ('ru', 'chat.limitWait.estimated', $json$"{agent} достиг лимита использования и не сообщил, когда он вернётся. JayV сам повторит попытку примерно в {time}."$json$::jsonb),
  ('ru', 'chat.limitWait.resumeNow', $json$"Возобновить сейчас"$json$::jsonb),
  ('ru', 'chat.limitWait.resumeNow.title', $json$"Отправить этот запрос ещё раз сейчас, не дожидаясь возврата лимита"$json$::jsonb),
  ('ru', 'chat.limitWait.cancel', $json$"Не ждать"$json$::jsonb),
  ('ru', 'chat.limitWait.cancel.title', $json$"Перестать ждать лимит; запрос останется неудавшимся и его можно отправить вручную"$json$::jsonb),
  ('ru', 'jev.resumeLimit', $json$"Возобновлять запросы, когда вернётся лимит использования агента"$json$::jsonb),
  ('ru', 'jev.resumeLimit.hint', $json$"Когда агент исчерпывает лимит использования и ни один другой агент не может принять запрос, JayV сохраняет запрос и сам отправляет его снова, когда агент сообщает, что лимит вернётся (с небольшим запасом). Если агент не называет время, повторная попытка через 30 минут. Запрос, который всё ещё упирается в лимит после трёх автоматических возобновлений, перестаёт ждать. Если выключить, запрос остаётся неудавшимся, пока вы не отправите его снова."$json$::jsonb),
  ('ru', 'palette.resumeNow', $json$"Возобновить сейчас запрос, ожидающий лимит использования"$json$::jsonb),
  ('ru', 'palette.cancelLimitWait', $json$"Перестать ждать лимит использования"$json$::jsonb),
  ('ru', 'whatsNew.item.limitResume.title', $json$"Запросы возобновляются, когда возвращается лимит использования"$json$::jsonb),
  ('ru', 'whatsNew.item.limitResume.detail', $json$"Когда агент достигает лимита использования и ни один другой агент не может принять запрос, запрос не просто завершается ошибкой: JayV читает, когда агент сообщает о возврате лимита, сохраняет запрос и сам отправляет его снова в это время, даже если приложение было закрыто. Чат показывает ожидание со временем и позволяет возобновить сразу или перестать ждать. В Настройках › Jev есть переключатель, чтобы отключить это."$json$::jsonb),
  ('ru', 'docs.limitResume.title', $json$"Возобновление после лимита использования"$json$::jsonb),
  ('ru', 'docs.limitResume.summary', $json$"Когда агент достигает лимита использования и ни один другой агент не может принять запрос, JayV сохраняет запрос и сам отправляет его снова, когда агент сообщает, что лимит вернулся."$json$::jsonb),
  ('ru', 'docs.limitResume.usage', $json$"Включено по умолчанию (Настройки › Jev › Возобновлять запросы, когда вернётся лимит использования агента). Когда все агенты, которые могли бы ответить, исчерпали лимит, запрос остаётся в чате неудавшимся с пометкой: какой агент остановился и в какое время JayV его возобновит — по вашему местному времени, с запасом в одну минуту. Если агент не сообщает, когда вернётся лимит, JayV повторяет попытку через 30 минут, и пометка говорит, что время приблизительное. Нажмите «Возобновить сейчас», чтобы отправить раньше, или «Не ждать», чтобы отменить автоматическое возобновление; запрос остаётся неудавшимся, а «Отправить снова» работает как обычно (оба действия есть и в Ctrl+K). Ожидание переживает закрытие приложения: если открыть его после назначенного времени, запрос будет отправлен. Если свободен другой включённый агент, существующий запасной вариант сразу передаёт ему запрос, и ничего не ждёт. Запрос, который всё ещё упирается в лимит после трёх автоматических возобновлений, перестаёт ждать."$json$::jsonb),
  ('ja', 'beat.limitWait', $json$"{agent} が利用上限に達しました。JayV は {time} にこのリクエストを再開します"$json$::jsonb),
  ('ja', 'beat.limitWait.estimated', $json$"{agent} が利用上限に達しましたが、いつ戻るかは示されませんでした。JayV は {time} ごろに再試行します"$json$::jsonb),
  ('ja', 'chat.limitWait', $json$"{agent} が利用上限に達しました。JayV は {time} にこのリクエストを自動で再開します。"$json$::jsonb),
  ('ja', 'chat.limitWait.estimated', $json$"{agent} が利用上限に達しましたが、いつ戻るかは示されませんでした。JayV は {time} ごろに自動で再試行します。"$json$::jsonb),
  ('ja', 'chat.limitWait.resumeNow', $json$"今すぐ再開"$json$::jsonb),
  ('ja', 'chat.limitWait.resumeNow.title', $json$"上限が戻るのを待たずに、このリクエストを今すぐ再送します"$json$::jsonb),
  ('ja', 'chat.limitWait.cancel', $json$"待たない"$json$::jsonb),
  ('ja', 'chat.limitWait.cancel.title', $json$"上限を待つのをやめます。リクエストは失敗のままで、手動で再送できます"$json$::jsonb),
  ('ja', 'jev.resumeLimit', $json$"エージェントの利用上限が戻ったらリクエストを再開する"$json$::jsonb),
  ('ja', 'jev.resumeLimit.hint', $json$"エージェントが利用上限を使い切り、リクエストを引き受けられる他のエージェントがいない場合、JayV はリクエストを保持し、エージェントが上限の復旧を知らせた時刻（少しの余裕を加えて）に自動で再送します。エージェントが時刻を示さない場合は 30 分後に再試行します。自動再開を 3 回行ってもまだ上限に当たるリクエストは待機をやめます。オフにすると、再送するまでリクエストは失敗のままです。"$json$::jsonb),
  ('ja', 'palette.resumeNow', $json$"利用上限を待っているリクエストを今すぐ再開"$json$::jsonb),
  ('ja', 'palette.cancelLimitWait', $json$"利用上限を待つのをやめる"$json$::jsonb),
  ('ja', 'whatsNew.item.limitResume.title', $json$"利用上限が戻るとリクエストが再開されます"$json$::jsonb),
  ('ja', 'whatsNew.item.limitResume.detail', $json$"エージェントが利用上限に達し、他のエージェントがリクエストを引き受けられない場合、リクエストは単に失敗するのではなく、JayV がエージェントの示す復旧時刻を読み取り、リクエストを保持してその時刻に自動で再送します。その間にアプリを閉じていても同じです。チャットには時刻つきで待機が表示され、今すぐ再開するか待つのをやめるかを選べます。設定 › Jev にオフにするスイッチがあります。"$json$::jsonb),
  ('ja', 'docs.limitResume.title', $json$"利用上限のあとで再開"$json$::jsonb),
  ('ja', 'docs.limitResume.summary', $json$"エージェントが利用上限に達し、他のエージェントがリクエストを引き受けられない場合、JayV はリクエストを保持し、エージェントが上限の復旧を知らせた時刻に自動で再送します。"$json$::jsonb),
  ('ja', 'docs.limitResume.usage', $json$"初期状態でオンです（設定 › Jev › エージェントの利用上限が戻ったらリクエストを再開する）。回答できるすべてのエージェントが上限を使い切ると、リクエストはチャットに失敗として残り、どのエージェントが止まったか、JayV が再開する時刻（現地時間、1 分の余裕つき）が表示されます。エージェントが上限の復旧時刻を示さない場合、JayV は 30 分後に再試行し、その時刻が推定であることが表示されます。「今すぐ再開」で前倒しで送信でき、「待たない」で自動再開を取り消せます。リクエストは失敗のままで、「再送」はこれまでどおり使えます（どちらも Ctrl+K にもあります）。待機はアプリを閉じても続きます。時刻を過ぎてから開くとリクエストが送信されます。有効な別のエージェントが空いていれば、既存の代替機能がすぐにそちらへ回し、待機は発生しません。自動再開を 3 回行ってもまだ上限に当たるリクエストは待機をやめます。"$json$::jsonb),
  ('de', 'beat.limitWait', $json$"{agent} hat sein Nutzungslimit erreicht; JayV setzt diese Anfrage um {time} fort"$json$::jsonb),
  ('de', 'beat.limitWait.estimated', $json$"{agent} hat sein Nutzungslimit erreicht und nicht gesagt, wann es zurückkommt; JayV versucht es etwa um {time} erneut"$json$::jsonb),
  ('de', 'chat.limitWait', $json$"{agent} hat sein Nutzungslimit erreicht. JayV setzt diese Anfrage um {time} von selbst fort."$json$::jsonb),
  ('de', 'chat.limitWait.estimated', $json$"{agent} hat sein Nutzungslimit erreicht und nicht gesagt, wann es zurückkommt. JayV versucht es etwa um {time} von selbst erneut."$json$::jsonb),
  ('de', 'chat.limitWait.resumeNow', $json$"Jetzt fortsetzen"$json$::jsonb),
  ('de', 'chat.limitWait.resumeNow.title', $json$"Diese Anfrage jetzt erneut senden, ohne auf die Rückkehr des Limits zu warten"$json$::jsonb),
  ('de', 'chat.limitWait.cancel', $json$"Nicht warten"$json$::jsonb),
  ('de', 'chat.limitWait.cancel.title', $json$"Nicht mehr auf das Limit warten; die Anfrage bleibt fehlgeschlagen und kann von Hand erneut gesendet werden"$json$::jsonb),
  ('de', 'jev.resumeLimit', $json$"Anfragen fortsetzen, wenn das Nutzungslimit des Agenten zurückkommt"$json$::jsonb),
  ('de', 'jev.resumeLimit.hint', $json$"Erschöpft ein Agent sein Nutzungslimit und kann kein anderer Agent die Anfrage übernehmen, behält JayV die Anfrage und sendet sie von selbst erneut, wenn der Agent sagt, dass das Limit zurückkommt (mit kleinem Aufschlag). Nennt der Agent keine Zeit, versucht JayV es nach 30 Minuten erneut. Eine Anfrage, die nach drei automatischen Fortsetzungen weiter am Limit scheitert, wartet nicht mehr. Ausgeschaltet bleibt die Anfrage fehlgeschlagen, bis du sie erneut sendest."$json$::jsonb),
  ('de', 'palette.resumeNow', $json$"Die auf das Nutzungslimit wartende Anfrage jetzt fortsetzen"$json$::jsonb),
  ('de', 'palette.cancelLimitWait', $json$"Nicht mehr auf das Nutzungslimit warten"$json$::jsonb),
  ('de', 'whatsNew.item.limitResume.title', $json$"Anfragen werden fortgesetzt, wenn das Nutzungslimit zurückkommt"$json$::jsonb),
  ('de', 'whatsNew.item.limitResume.detail', $json$"Erreicht ein Agent sein Nutzungslimit und kann kein anderer Agent die Anfrage übernehmen, schlägt sie nicht mehr einfach fehl: JayV liest, wann der Agent sagt, dass das Limit zurückkommt, behält die Anfrage und sendet sie zu dieser Zeit von selbst erneut, auch wenn die App zwischendurch geschlossen war. Der Chat zeigt das Warten mit der Uhrzeit und lässt dich sofort fortsetzen oder nicht mehr warten. In Einstellungen › Jev gibt es einen Schalter zum Ausschalten."$json$::jsonb),
  ('de', 'docs.limitResume.title', $json$"Nach dem Nutzungslimit fortsetzen"$json$::jsonb),
  ('de', 'docs.limitResume.summary', $json$"Erreicht ein Agent sein Nutzungslimit und kann kein anderer Agent die Anfrage übernehmen, behält JayV die Anfrage und sendet sie von selbst erneut, wenn der Agent sagt, dass das Limit zurückkommt."$json$::jsonb),
  ('de', 'docs.limitResume.usage', $json$"Standardmäßig an (Einstellungen › Jev › Anfragen fortsetzen, wenn das Nutzungslimit des Agenten zurückkommt). Haben alle Agenten, die antworten könnten, ihr Limit erschöpft, bleibt die Anfrage im Chat als fehlgeschlagen mit einem Hinweis stehen: welcher Agent gestoppt hat und wann JayV sie fortsetzt, in deiner Ortszeit, mit einer Minute Aufschlag. Sagt der Agent nicht, wann sein Limit zurückkommt, versucht JayV es nach 30 Minuten erneut, und der Hinweis nennt die Zeit eine Schätzung. Mit „Jetzt fortsetzen“ sendest du früher, mit „Nicht warten“ brichst du die automatische Fortsetzung ab; die Anfrage bleibt fehlgeschlagen, und „Erneut senden“ funktioniert wie immer (beides auch in Ctrl+K). Das Warten überdauert das Schließen der App: Öffnest du sie nach der Zeit wieder, wird die Anfrage gesendet. Ist ein anderer aktivierter Agent frei, übergibt der vorhandene Plan B ihm die Anfrage sofort, und nichts wartet. Eine Anfrage, die nach drei automatischen Fortsetzungen weiter am Limit scheitert, wartet nicht mehr."$json$::jsonb)
